//#region src/CmcdData.d.ts
/**
* CMCD version 1 data.
*
* Overrides keys whose types differ in version 1. For example, `bl` and
* `br` are integers instead of inner lists.
*
* @public
*/
type CmcdV1Data = Omit<CmcdRequest, keyof CmcdV1 | "v"> & CmcdV1 & {
  v?: 1;
};
/**
* CMCD version 2 data.
*
* Includes all request, event, and response mode keys with version 2
* types.
*
* @public
*/
type CmcdV2Data = Omit<Cmcd, "v"> & {
  v: 2;
};
/**
* A CMCD data object that is either version 1 or version 2.
*
* The `v` property is the discriminator:
*
* - When `v` is `2`, the type narrows to {@link CmcdV2Data} with
*   inner-list values and event/response keys.
* - When `v` is `1` or absent, the type narrows to {@link CmcdV1Data}
*   with scalar values.
*
* @example
* ```ts
* function process(data: CmcdData) {
*   if (data.v === 2) {
*     // data.bl is CmcdObjectTypeList | undefined
*   } else {
*     // data.bl is number | undefined
*   }
* }
* ```
*
* @public
*/
type CmcdData = CmcdV1Data | CmcdV2Data;
