//#region src/CmcdDecodeOptions.d.ts
/**
* Options for decoding CMCD data.
*
* @public
*/
type CmcdDecodeOptions = {
  /**
  * When `true`, up-converts version 1 data to version 2 format by wrapping
  * scalar values in arrays for inner-list keys. Examples: `bl`, `br`, `mtp`.
  *
  * The result has a consistent structure regardless of the source version.
  * This conversion corresponds to the down-conversion during encoding.
  *
  * @defaultValue false
  */
  convertToLatest?: boolean;
  /**
  * Controls how the decoded data represents RFC 8941 token values. If
  * omitted, tokens decode to plain strings, which re-encoding cannot
  * distinguish from string values. `true` decodes tokens as registry
  * `Symbol`s and `false` as `SfToken` instances. Either preserved
  * representation re-encodes as a bare token, so a decode/encode round
  * trip reproduces the wire bytes.
  */
  useSymbol?: boolean;
};
//#endregion
//#region src/CmcdTransformRequest.d.ts
/**
* The media request passed to a report transform, as a read-only view.
*
* The request is context only. A transform reads it to decide what to do with
* the report. A transform must not mutate the request, which belongs to the
* caller and may still be in use. Every member is `readonly`, and `customData`
* is readonly at every depth, so nested values cannot be written either.
*
* By default `customData` values are `unknown` rather than `any`, because the
* library cannot know the player's fields. Narrow with a cast or bracket access
* to read player-specific fields:
*
* ```ts
* transform: (data, request) =>
* 	request?.customData?.['requestType'] === 'segment' ? data : null
* ```
*
* Supply `C` to describe the player's own `customData` instead, and those
* reads become typed dot access. Annotating one transform is enough: the
* reporter infers `C` for every other transform in the same configuration.
*
* ```ts
* type PlayerData = { requestType: string; };
*
* const segmentsOnly: CmcdEventReportTransform<PlayerData> = (data, request) =>
* 	request?.customData?.requestType === 'segment' ? data : null
* ```
*
* This type wraps `C` in {@link DeepReadonly}, so a nested `C` keeps both the
* read-only guarantee and typed reads.
*
* Two limits apply. A mutable body such as `FormData` or `URLSearchParams`
* has mutating methods of its own that no type can block. JavaScript callers
* get no enforcement at all. Both kinds of mutation are unsupported, and the
* outgoing report may reflect them.
*
* @typeParam C - The type of the player's `customData`. Defaults to
*                `Record<string, unknown>`.
*
* @public
*/
type CmcdTransformRequest<C = Record<string, unknown>> = Readonly<Omit<HttpRequest, "customData" | "headers">> & {
  /**
  * The headers associated with the request.
  */
  readonly headers?: Readonly<Record<string, string>>;
  /**
  * Any custom data the caller attached to the request, including the
  * player's own fields.
  */
  readonly customData?: DeepReadonly<C>;
};
//#endregion
//#region src/CmcdEventReportTransform.d.ts
/**
* Transforms an event-mode CMCD report before the reporter queues it for
* its target.
*
* Return the data to continue, or `null` to cancel the report. The
* `data` argument is a per-target copy, so mutating it affects neither
* the reporter's persistent data nor the reports for other targets.
*
* The `request` argument is the media request that triggered the event
* (for events recorded through
* {@link CmcdReporter.recordResponseReceived}), otherwise `undefined`.
* The request is a read-only view for context only. A transform must
* not mutate it. See {@link CmcdTransformRequest}.
*
* The reporter rewrites `e` and `sid` and assigns `sn` and `msd` after this
* function returns, so values written to those keys are overwritten.
*
* Must not throw. Exceptions propagate to the caller that recorded the
* event. For time-interval events, that caller is the interval timer.
*
* @typeParam C - The type of the player's `customData` on the request.
*                Defaults to `Record<string, unknown>`, whose values are
*                `unknown` and read with bracket access.
*
* @public
*/
type CmcdEventReportTransform<C = Record<string, unknown>> = (data: Cmcd, request: CmcdTransformRequest<C> | undefined) => Cmcd | null;
//#endregion
//#region src/CmcdReportConfig.d.ts
/**
* Configuration for a CMCD report.
*
* @public
*/
type CmcdReportConfig = {
  /**
  * The version of the CMCD specification to use.
  *
  * @defaultValue `CMCD_V2`
  */
  version?: CmcdVersion;
  /**
  * The list of CMCD keys to include in the report. If omitted, no keys
  * are reported. In event mode, this list cannot remove `e`, `ts`, or the
  * required key of the event type. Examples of required keys: `sta` for a
  * play state change, `ec` for an error, `url` for a response received.
  *
  * @defaultValue `undefined`
  */
  enabledKeys?: CmcdKey[];
};
//#endregion
//#region src/CmcdEventReportConfig.d.ts
/**
* Configuration for a CMCD event report.
*
* @typeParam C - The type of the player's `customData` on the request that
*                triggered the event. Defaults to `Record<string, unknown>`.
*
* @public
*/
type CmcdEventReportConfig<C = Record<string, unknown>> = CmcdReportConfig & {
  /**
  * The version of the CMCD protocol to use. Event reporting
  * requires version 2.
  *
  * @defaultValue `CMCD_V2`
  */
  version?: typeof CMCD_V2;
  /**
  * The URL where the reporter sends CMCD event reports.
  */
  url: string;
  /**
  * The events to report. If the caller provides no events,
  * the event target is effectively disabled.
  *
  * @defaultValue `undefined`
  */
  events?: CmcdEventType[];
  /**
  * When the time interval event is sent, the interval in seconds at
  * which the reporter sends it.
  *
  * @defaultValue `CMCD_DEFAULT_TIME_INTERVAL`
  *
  * @see {@link CMCD_DEFAULT_TIME_INTERVAL}
  */
  interval?: number;
  /**
  * The number of events to batch before sending the report.
  *
  * @defaultValue `1`
  */
  batchSize?: number;
  /**
  * Transform applied to each of this target's event reports before
  * it is queued. Return the data to continue, or `null` to cancel
  * the report for this target.
  *
  * The transform is scoped to this target only. Targets that share a
  * collector URL each run their own transform. Other targets that
  * accept the event still receive a report cancelled by this transform.
  *
  * @defaultValue `undefined`
  *
  * @example
  * {@includeCode ../test/CmcdReporter.test.ts#example-transform}
  */
  transform?: CmcdEventReportTransform<C>;
};
//#endregion
